import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate/spring

const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type MorphingCardGraphProps = Record<string, any>;

const MorphingCardGraph: React.FC<MorphingCardGraphProps> = ({
  backgroundColor = "#111114",
  transparentBackground = false,
  durationInSeconds = 8,
  cardBackgroundColor = "#ffffff",
  title = "World Population Growth",
  subtitle = "1900 - 2000 (in billions)",
  barWidth = 86,
  bars = [
    { label: "1900", value: 1.68, color: "#4285F4" },
    { label: "1910", value: 1.78, color: "#EA4335" },
    { label: "1920", value: 1.98, color: "#FBBC04" },
    { label: "1930", value: 2.18, color: "#34A853" },
    { label: "1940", value: 2.38, color: "#4285F4" },
    { label: "1950", value: 2.52, color: "#FA7B17" },
    { label: "1960", value: 3.02, color: "#EA4335" },
    { label: "1970", value: 3.70, color: "#FBBC04" },
    { label: "1980", value: 4.44, color: "#34A853" },
    { label: "1990", value: 5.28, color: "#4285F4" },
    { label: "2000", value: 6.08, color: "#FA7B17" },
  ],
  yAxisMax = 7,
  promptText = "1 sentence long prompt.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing constants (fixed frames to preserve distinct motion arcs regardless of duration)
  const barStart = 45;
  const morphStart = 140;
  const typeStart = 170;
  const iconStart = 200;

  // Geometry references
  const startWidth = 1400 * s;
  const startHeight = 800 * s;
  const startRadius = 32 * s;

  const endWidth = 1000 * s;
  const endHeight = 120 * s;
  const endRadius = 60 * s;

  const yLabels = Array.from({ length: yAxisMax + 1 }, (_, i) => yAxisMax - i);

  // Phase 1: Entrance
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const cardTy = interpolate(entranceProgress, [0, 1], [800 * s, 0]);
  const cardRxEntrance = interpolate(entranceProgress, [0, 1], [60, 0]);
  const cardOpacity = interpolate(entranceProgress, [0, 0.2], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Floating 3D effect: slow continuous breathing/floating rotation and translation
  const floatRx = Math.sin(frame * 0.03) * 5; // slow pitch tilt
  const floatRy = Math.cos(frame * 0.025) * 6; // slow yaw tilt
  const floatRz = Math.sin(frame * 0.015) * 1.5; // slight roll
  const floatTy = Math.sin(frame * 0.04) * (12 * s); // slow bobbing up/down

  // Combine entrance rotation with the continuous floating angle
  const cardRotationX = cardRxEntrance + floatRx;

  // Phase 3: Morph
  const morphProgress = spring({
    frame: frame - morphStart,
    fps,
    config: { damping: 14, mass: 1 },
  });

  const currentWidth = interpolate(morphProgress, [0, 1], [startWidth, endWidth]);
  const currentHeight = interpolate(morphProgress, [0, 1], [startHeight, endHeight]);
  const currentRadius = interpolate(morphProgress, [0, 1], [startRadius, endRadius]);

  const graphOpacity = interpolate(morphProgress, [0, 0.3], [1, 0], {
    extrapolateRight: "clamp",
  });
  const promptOpacity = interpolate(morphProgress, [0.7, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Phase 4: Typing
  const maxLen = Math.max(1, promptText.length);
  const typeProgress = interpolate(
    frame,
    [typeStart, typeStart + 30],
    [0, maxLen],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const displayedText = promptText.substring(0, Math.floor(typeProgress));

  // Phase 5: Icon entrance
  const iconProgress = spring({
    frame: frame - iconStart,
    fps,
    config: { damping: 12 },
  });
  const iconOpacity = interpolate(iconProgress, [0, 1], [0, 1]);
  const iconScale = interpolate(iconProgress, [0, 1], [0.5, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* 3D Perspective Wrapper */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: "translate(-50%, -50%)",
          perspective: `${2000 * s}px`,
          width: startWidth,
          height: startHeight,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* The Animating Card */}
        <div
          style={{
            width: currentWidth,
            height: currentHeight,
            borderRadius: currentRadius,
            backgroundColor: cardBackgroundColor,
            transform: `translateY(${cardTy + floatTy}px) rotateX(${cardRotationX}deg) rotateY(${floatRy}deg) rotateZ(${floatRz}deg)`,
            transformOrigin: "center center",
            boxShadow: `0 ${20 * s}px ${40 * s}px rgba(0,0,0,0.2), 0 ${4 * s}px ${8 * s}px rgba(0,0,0,0.1)`,
            opacity: cardOpacity,
            overflow: "hidden",
            position: "relative",
            transition: "none",
          }}
        >
          {/* Graph Content */}
          <div
            style={{
              position: "absolute",
              width: startWidth,
              height: startHeight,
              left: "50%",
              top: "50%",
              transform: "translate(-50%, -50%)",
              opacity: graphOpacity,
              padding: `${60 * s}px ${80 * s}px`,
              display: "flex",
              flexDirection: "column",
              pointerEvents: "none",
            }}
          >
            {/* Header */}
            <div style={{ textAlign: "center", marginBottom: `${40 * s}px` }}>
              <h1
                style={{
                  fontFamily: playfairFamily,
                  fontSize: `${48 * s}px`,
                  margin: 0,
                  color: "#111",
                  fontWeight: 600,
                }}
              >
                {title}
              </h1>
              <p
                style={{
                  fontFamily: interFamily,
                  fontSize: `${18 * s}px`,
                  margin: `${8 * s}px 0 0 0`,
                  color: "#666",
                }}
              >
                {subtitle}
              </p>
            </div>

            {/* Chart Container */}
            <div
              style={{
                flex: 1,
                position: "relative",
                marginLeft: `${40 * s}px`,
                borderBottom: `${2 * s}px solid #222`,
              }}
            >
              {/* Grid Lines and Y-Axis Labels */}
              {yLabels.map((y, i) => {
                const topPercent = (i / (yLabels.length - 1)) * 100;
                return (
                  <React.Fragment key={y}>
                    <div
                      style={{
                        position: "absolute",
                        left: 0,
                        right: 0,
                        top: `${topPercent}%`,
                        height: `${1 * s}px`,
                        backgroundColor: y === 0 ? "transparent" : "#eaeaea",
                        zIndex: 0,
                      }}
                    />
                    <div
                      style={{
                        position: "absolute",
                        right: "100%",
                        top: `${topPercent}%`,
                        marginRight: `${16 * s}px`,
                        transform: "translateY(-50%)",
                        fontFamily: interFamily,
                        fontSize: `${14 * s}px`,
                        color: "#888",
                        fontWeight: 500,
                      }}
                    >
                      {y}B
                    </div>
                  </React.Fragment>
                );
              })}

              {/* Bars and X-Axis Labels */}
              <div
                style={{
                  position: "absolute",
                  left: `${20 * s}px`,
                  right: `${20 * s}px`,
                  top: 0,
                  bottom: 0,
                  display: "flex",
                  alignItems: "flex-end",
                  justifyContent: "space-between",
                  zIndex: 1,
                }}
              >
                {bars.map((bar, i) => {
                  const barProgress = spring({
                    frame: frame - (barStart + i * 4),
                    fps,
                    config: { damping: 12 },
                  });

                  const heightPercent = (bar.value / yAxisMax) * 100;
                  const safeHeight = Math.max(0.001, heightPercent);
                  const h = interpolate(barProgress, [0, 1], [0, safeHeight], {
                    extrapolateRight: "clamp",
                  });

                  return (
                    <div
                      key={i}
                      style={{
                        height: "100%",
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        justifyContent: "flex-end",
                        width: `${barWidth * s}px`,
                        position: "relative",
                      }}
                    >
                      {/* Live Data Label */}
                      <div
                        style={{
                          fontFamily: interFamily,
                          fontSize: `${14 * s}px`,
                          color: "#111",
                          fontWeight: 700,
                          marginBottom: `${8 * s}px`,
                          opacity: interpolate(
                            barProgress,
                            [0.8, 1],
                            [0, 1],
                            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                          ),
                        }}
                      >
                        {bar.value > 0 ? `${bar.value}B` : ""}
                      </div>

                      {/* Bar Fill */}
                      <div
                        style={{
                          width: "100%",
                          height: `${bar.value === 0 ? 0 : h}%`,
                          backgroundColor: bar.color,
                          borderTopLeftRadius: `${4 * s}px`,
                          borderTopRightRadius: `${4 * s}px`,
                        }}
                      />

                      {/* Static X-Axis Label */}
                      <div
                        style={{
                          position: "absolute",
                          bottom: `-${32 * s}px`,
                          fontFamily: interFamily,
                          fontSize: `${12 * s}px`,
                          color: "#666",
                          fontWeight: 500,
                        }}
                      >
                        {bar.label}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Prompt Morph Content */}
          <div
            style={{
              position: "absolute",
              width: endWidth,
              height: endHeight,
              left: "50%",
              top: "50%",
              transform: "translate(-50%, -50%)",
              opacity: promptOpacity,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: `0 ${32 * s}px 0 ${48 * s}px`,
              pointerEvents: "none",
            }}
          >
            <div
              style={{
                fontFamily: interFamily,
                fontSize: `${36 * s}px`,
                color: "#111",
                fontWeight: 400,
              }}
            >
              {displayedText}
            </div>

            <div
              style={{
                width: `${48 * s}px`,
                height: `${48 * s}px`,
                borderRadius: "50%",
                border: `${2 * s}px solid #111`,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                opacity: iconOpacity,
                transform: `scale(${iconScale})`,
              }}
            >
              <svg
                width={24 * s}
                height={24 * s}
                viewBox="0 0 24 24"
                fill="none"
                stroke="#111"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M12 19V5M5 12l7-7 7 7" />
              </svg>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MorphingCardGraph;